// feedDigestItem is one product surfaced by `feed digest`, extracted
// generically from the delta-feed response (see extractDiscountedNodes).
type feedDigestItem struct {
	ProductID          string          `json:"product_id,omitempty"`
	Title              string          `json:"title,omitempty"`
	DiscountPercentage float64         `json:"discount_percentage"`
	Raw                json.RawMessage `json:"-"`
}

var feedNextVersionRE = regexp.MustCompile(`fromVersion/([0-9]+)`)

// extractDiscountedNodes walks an arbitrary JSON response looking for
// objects carrying a "discountPercentage" field, recording it alongside
// whatever identifying fields (productId/id/sku, title/productTitle/name)
// are present as siblings. The Affiliate Delta Feed response shape nests
// products under vendor-specific wrapper keys (productInfo /
// productBaseInfoV1 in Flipkart's documented v1.0 shape); walking
// generically rather than hardcoding that nesting keeps this resilient to
// wrapper variations the spec didn't pin down as "verified live" (unlike
// the search/product JSON-LD shapes).
func extractDiscountedNodes(raw json.RawMessage) []feedDigestItem {
	var v any
	if err := json.Unmarshal(raw, &v); err != nil {
		return nil
	}
	var out []feedDigestItem
	var walk func(node any)
	walk = func(node any) {
		switch n := node.(type) {
		case map[string]any:
			if dp, ok := numericField(n, "discountPercentage"); ok {
				item := feedDigestItem{DiscountPercentage: dp}
				if id, ok := stringField(n, "productId", "id", "sku"); ok {
					item.ProductID = id
				}
				if t, ok := stringField(n, "title", "productTitle", "name"); ok {
					item.Title = t
				}
				if b, err := json.Marshal(n); err == nil {
					item.Raw = b
				}
				out = append(out, item)
			}
			for _, val := range n {
				walk(val)
			}
		case []any:
			for _, val := range n {
				walk(val)
			}
		}
	}
	walk(v)
	return out
}

func numericField(obj map[string]any, key string) (float64, bool) {
	v, ok := obj[key]
	if !ok {
		return 0, false
	}
	f, ok := v.(float64)
	return f, ok
}

func stringField(obj map[string]any, keys ...string) (string, bool) {
	for _, k := range keys {
		if v, ok := obj[k]; ok {
			if s, ok := v.(string); ok && s != "" {
				return s, true
			}
		}
	}
	return "", false
}

// extractNextFeedVersion attempts to determine the feed version to store
// as the cursor for the next `feed digest` run. Prefers a "nextUrl" field
// (the documented pagination mechanism for Flipkart's delta feed) and
// falls back to a top-level version-shaped field. Returns ok=false rather
// than guessing when neither is present.
func extractNextFeedVersion(raw json.RawMessage) (string, bool) {
	var obj map[string]any
	if err := json.Unmarshal(raw, &obj); err != nil {
		return "", false
	}
	if nextURL, ok := obj["nextUrl"].(string); ok && nextURL != "" {
		if m := feedNextVersionRE.FindStringSubmatch(nextURL); m != nil {
			return m[1], true
		}
	}
	for _, key := range []string{"version", "currentVersion", "feedVersion"} {
		v, ok := obj[key]
		if !ok {
			continue
		}
		switch vv := v.(type) {
		case string:
			if vv != "" {
				return vv, true
			}
		case float64:
			return fmt.Sprintf("%d", int64(vv)), true
		}
	}
	return "", false
}

func newFeedDigestCmd(flags *rootFlags) *cobra.Command {
	var flagTrackingID string

	cmd := &cobra.Command{
		Use:   "digest <category>",
		Short: "Pull the Affiliate Delta Feed without hand-tracking fromVersion, ranked by discount change.",
		Long: `Calls the official Affiliate Delta Feed API for a category using the
last fromVersion this CLI remembers for it (starting at "1" the first
time), ranks returned products by |discountPercentage| descending, and
updates the stored cursor so the next run only sees what's new.

Requires FLIPKART_AFFILIATE_ID and FLIPKART_AFFILIATE_TOKEN (or pass
--tracking-id to override the tracking ID).`,
		Example:     "  flipkart-pp-cli feed digest mobiles",
		Annotations: map[string]string{"pp:endpoint": "feed.digest", "mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			category := args[0]

			trackingID := flagTrackingID
			if trackingID == "" {
				trackingID = os.Getenv("FLIPKART_AFFILIATE_ID")
			}

			// dry-run must short-circuit before the required-credential
			// check so `--dry-run` always succeeds (per the
			// Verify-friendly RunE convention) regardless of whether
			// FLIPKART_AFFILIATE_ID/FLIPKART_AFFILIATE_TOKEN are set.
			// The stored cursor lookup is a local, side-effect-free read,
			// so it's safe to do before the dry-run check too and makes
			// the preview message more informative.
			db, err := store.OpenWithContext(cmd.Context(), defaultDBPath("flipkart-pp-cli"))
			if err != nil {
				return fmt.Errorf("opening local database: %w", err)
			}
			defer db.Close()
			if err := db.EnsureFlipkartSchema(); err != nil {
				return err
			}

			fromVersion, hadCursor, err := db.GetFlipkartFeedCursor(category)
			if err != nil {
				return fmt.Errorf("reading stored feed cursor: %w", err)
			}
			if !hadCursor || fromVersion == "" {
				fromVersion = "1"
			}

			if dryRunOK(flags) {
				trackingIDMsg := "(not set)"
				if trackingID != "" {
					trackingIDMsg = "****" + lastN(trackingID, 4)
				}
				fmt.Fprintf(cmd.ErrOrStderr(), "would fetch delta feed for category %q from version %q (tracking id %s)\n(dry run - no request sent)\n",
					category, fromVersion, trackingIDMsg)
				return nil
			}

			if trackingID == "" || os.Getenv("FLIPKART_AFFILIATE_TOKEN") == "" {
				return authErr(fmt.Errorf("feed digest requires both FLIPKART_AFFILIATE_ID and FLIPKART_AFFILIATE_TOKEN to be set (or pass --tracking-id for the ID)"))
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}
			c = c.WithTier("affiliate")

			path := "/1.0/deltaFeeds/{tracking_id}/category/{category}/fromVersion/{from_version}.json"
			path = replacePathParam(path, "tracking_id", trackingID)
			path = replacePathParam(path, "category", category)
			path = replacePathParam(path, "from_version", fromVersion)

			data, _, err := resolveRead(cmd.Context(), c, flags, "feed", false, path, map[string]string{}, nil)
			if err != nil {
				return classifyAPIError(err, flags)
			}

			ranked := extractDiscountedNodes(data)
			sort.SliceStable(ranked, func(i, j int) bool {
				return math.Abs(ranked[i].DiscountPercentage) > math.Abs(ranked[j].DiscountPercentage)
			})
			if cliutil.IsDogfoodEnv() && len(ranked) > 1 {
				ranked = ranked[:1]
			}

			result := map[string]any{
				"category":             category,
				"from_version_used":    fromVersion,
				"ranked_products":      ranked,
				"ranked_product_count": len(ranked),
			}
			if newVersion, ok := extractNextFeedVersion(data); ok && newVersion != fromVersion {
				if err := db.SetFlipkartFeedCursor(category, newVersion); err != nil {
					return fmt.Errorf("storing new feed cursor: %w", err)
				}
				result["new_version"] = newVersion
				result["cursor_updated"] = true
			} else {
				result["cursor_updated"] = false
				result["note"] = "could not determine the next feed version from the API response; cursor left at " + fromVersion
			}

			return printJSONFiltered(cmd.OutOrStdout(), result, flags)
		},
	}
	cmd.Flags().StringVar(&flagTrackingID, "tracking-id", "", "Affiliate tracking ID override (defaults to FLIPKART_AFFILIATE_ID)")
	return cmd
}

func lastN(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[len(s)-n:]
}
